const icon=paths=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths}</svg>`;
const ICONS={
  myday:icon('<circle cx="12" cy="12" r="3.25"/><path d="M12 2.5v2M12 19.5v2M2.5 12h2M19.5 12h2M5.3 5.3l1.4 1.4M17.3 17.3l1.4 1.4M18.7 5.3l-1.4 1.4M6.7 17.3l-1.4 1.4"/>'),
  important:icon('<path d="m12 3.1 2.72 5.51 6.08.88-4.4 4.29 1.04 6.06L12 17l-5.44 2.84 1.04-6.06-4.4-4.29 6.08-.88z"/>'),
  planned:icon('<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M8.5 8v8M12 8v8M15.5 8v8"/>'),
  assigned:icon('<circle cx="12" cy="7.5" r="3.2"/><path d="M5.5 19c.5-4 2.7-6 6.5-6s6 2 6.5 6c-3.7 1.7-9.3 1.7-13 0Z"/>'),
  flagged:icon('<path d="M6 21V3M6 4h11l-2.5 4L17 12H6"/>'),
  tasks:icon('<path d="m4 10 8-6 8 6v9a1 1 0 0 1-1 1h-5v-6h-4v6H5a1 1 0 0 1-1-1z"/>'),
  list:icon('<path d="M4 7h16M4 12h16M4 17h16"/>')
};
const builtIns=[['myday','My Day'],['important','Important'],['planned','Planned'],['assigned','Assigned to me'],['flagged','Flagged email'],['tasks','Tasks']];
const themes=[['blue','#536fa5'],['violet','#8b63ad'],['rose','#c95678'],['coral','#d75e5c'],['green','#3e987a'],['cyan','#3c9392'],['slate','#82909a'],['sky','#6fa7da'],['lilac','#b69aca'],['blush','#e59aac'],['sand','#dfa481'],['mint','#73b99f'],['aqua','#58aaa5'],['fog','#a4b1bb'],['night','linear-gradient(145deg,#13243f,#566f8c 55%,#d7a774)'],['forest','linear-gradient(145deg,#123a32,#29845d 55%,#88b65d)'],['sunset','linear-gradient(145deg,#483b69,#cc6d73 55%,#f1bd7a)']];
const sampleTasks=[
  ['Organize this week\'s project plan','tasks',true,0],['Review meeting notes and capture action items','tasks',false,1],['Focus for at least one hour','tasks',false,1],['Schedule annual health check','tasks',false,0],['Call family','tasks',true,0],['Organize desk and files','daily',false,0],['Complete product prototype','work',true,0],['Buy coffee beans','tasks',false,0]
].map((x,i)=>({id:'t'+i,title:x[0],list:x[1],important:x[2],myDay:!!x[3],completed:false,due:i===0?todayISO():null,reminder:null,repeat:null,note:'',steps:[],created:Date.now()-i*3600000}));
const initial={view:'myday',lists:[{id:'daily',name:'Daily routine'},{id:'work',name:'Work plan'},{id:'reading',name:'Reading list'}],groups:[],tasks:sampleTasks,selected:null,search:'',completedOpen:true,sidebarOpen:false,suggestions:false,moreOpen:false,theme:'night',sortMode:'created',editingListId:null,editingGroupId:null};
let state=load();
function todayISO(){const d=new Date();return d.toISOString().slice(0,10)}
function load(){try{const saved={...structuredClone(initial),...JSON.parse(localStorage.getItem('todo-state')||'{}')};const demoNames=['Set today\'s top three priorities','Reply to project updates','Organize the Downloads folder','Finish the product requirements draft','Read an industry report for 20 minutes','Schedule next week\'s meeting','Update the personal learning plan','Back up important work files','Clear unread inbox messages','Buy this week\'s essentials','Complete an English listening exercise','Write today\'s work review','Check the monthly budget','Organize the desk and workspace','Prepare tomorrow\'s meeting materials','Confirm weekend plans with friends','Update the reading list','Take a 30-minute walk','Plan the next milestone','Prepare tomorrow\'s to-do list'];if(!saved.demo20Seeded){const current=saved.tasks.filter(t=>t.myDay&&!t.completed).length;demoNames.slice(0,Math.max(0,20-current)).forEach((title,i)=>saved.tasks.push({id:'demo-'+i+'-'+Date.now(),title,list:'tasks',important:i%7===0,myDay:true,completed:false,due:i%6===0?todayISO():null,reminder:null,repeat:null,note:'',steps:[],created:Date.now()-100000-i}));saved.demo20Seeded=true}if(!saved.englishUiMigrated){const defaults={daily:'Daily routine',work:'Work plan',reading:'Reading list'};saved.lists.forEach(list=>{if(defaults[list.id])list.name=defaults[list.id]});saved.tasks.forEach(task=>{const sample=sampleTasks.find(item=>item.id===task.id);if(sample)task.title=sample.title;const match=/^demo-(\d+)-/.exec(task.id);if(match&&demoNames[+match[1]])task.title=demoNames[+match[1]];task.repeat=({每天:'Daily',每周:'Weekly',每月:'Monthly',每年:'Yearly'})[task.repeat]||task.repeat});saved.englishUiMigrated=true}return saved}catch{return structuredClone(initial)}}
function save(){localStorage.setItem('todo-state',JSON.stringify({...state,selected:null,suggestions:false,sidebarOpen:false}))}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function activeTasks(){return state.tasks.filter(t=>!t.completed)}
function countFor(id){return activeTasks().filter(t=>matchesView(t,id)).length}
function matchesView(t,v=state.view){if(v==='myday')return t.myDay;if(v==='important')return t.important;if(v==='planned')return !!t.due;if(v==='assigned'||v==='flagged')return false;if(v==='tasks')return t.list==='tasks';return t.list===v}
function viewInfo(){const bi=builtIns.find(x=>x[0]===state.view);if(bi)return{id:bi[0],name:bi[1],icon:ICONS[bi[0]]};const l=state.lists.find(x=>x.id===state.view);return{id:l?.id||'tasks',name:l?.name||'Tasks',icon:ICONS.list}}
function filtered(){const q=state.search.trim().toLowerCase();let tasks=state.tasks.filter(t=>q?t.title.toLowerCase().includes(q):matchesView(t));return tasks.sort((a,b)=>state.sortMode==='alpha'?a.title.localeCompare(b.title,'en'):state.sortMode==='important'?Number(b.important)-Number(a.important):b.created-a.created)}
function render(){renderSidebar();renderMain();renderDetail();renderSuggestions();save()}
function listRow(l,insideGroup=false){return `<button class="nav-item ${insideGroup?'group-list ':''}${state.view===l.id?'active':''}" data-view="${l.id}" draggable="true" data-list-drag="${l.id}"><span class="nav-icon">${ICONS.list}</span>${state.editingListId===l.id?`<input class="inline-name" data-list-name="${l.id}" value="${esc(l.name)}" aria-label="List name">`:`<span class="nav-label">${esc(l.name)}</span>`}${countFor(l.id)?`<span class="count">${countFor(l.id)}</span>`:''}</button>`}
function groupBlock(g){const lists=state.lists.filter(l=>l.groupId===g.id);return `<div class="group-block ${g.collapsed?'collapsed':''}" data-group-drop="${g.id}"><button class="group-row" data-action="toggle-group" data-id="${g.id}"><span class="group-folder">▣</span>${state.editingGroupId===g.id?`<input class="inline-name" data-group-name="${g.id}" value="${esc(g.name)}" aria-label="Group name">`:`<span class="group-name">${esc(g.name)}</span>`}<span class="group-chevron">${g.collapsed?'⌄':'⌃'}</span></button>${g.collapsed?'':`<div class="group-body">${lists.length?lists.map(l=>listRow(l,true)).join(''):'<div class="group-drop-hint">Drag here to add lists</div>'}</div>`}</div>`}
function renderSidebar(){const s=document.querySelector('#sidebar');s.className='sidebar'+(state.sidebarOpen?' mobile-open':'');s.innerHTML=`<div class="profile"><div class="avatar">J</div><div class="profile-copy"><div class="profile-name">My account</div><div class="profile-mail">Focus on what matters today</div></div></div><div class="search-wrap"><input id="search" value="${esc(state.search)}" placeholder="Search" aria-label="Search tasks"><span class="search-icon">⌕</span></div><div class="nav-scroll">${builtIns.map(([id,name],i)=>`${i===6?'<div class="nav-divider"></div>':''}<button class="nav-item ${state.view===id?'active':''}" data-view="${id}" style="--nav-color:${id==='important'?'#f0a5b7':id==='planned'?'#78d1c9':'#7eafff'}"><span class="nav-icon">${ICONS[id]}</span><span class="nav-label">${name}</span>${countFor(id)?`<span class="count">${countFor(id)}</span>`:''}</button>`).join('')}<div class="nav-divider"></div>${state.lists.filter(l=>!l.groupId).map(l=>listRow(l)).join('')}${(state.groups||[]).map(groupBlock).join('')}</div><div class="new-list"><button class="add-list has-tooltip" data-action="new-list" data-tooltip="New list (Ctrl + L)&#10;Add a list" aria-label="New list"><span class="add-list-plus">＋</span><span>New list</span></button><button class="group-btn has-tooltip" data-action="new-group" data-tooltip="Create a new group" aria-label="Create a new group"><span class="group-create-icon"></span></button></div>`;
  s.querySelector('#search').addEventListener('input',e=>{state.search=e.target.value;renderMain()});s.querySelectorAll('[data-list-drag]').forEach(row=>row.addEventListener('dragstart',e=>e.dataTransfer.setData('text/plain',row.dataset.listDrag)));s.querySelectorAll('[data-group-drop]').forEach(group=>{group.addEventListener('dragover',e=>{e.preventDefault();group.classList.add('drag-over')});group.addEventListener('dragleave',()=>group.classList.remove('drag-over'));group.addEventListener('drop',e=>{e.preventDefault();const list=state.lists.find(l=>l.id===e.dataTransfer.getData('text/plain')),target=(state.groups||[]).find(g=>g.id===group.dataset.groupDrop);if(list&&target){list.groupId=target.id;target.collapsed=false;render()}})});const editor=s.querySelector('.inline-name');if(editor){editor.focus();editor.select();const finish=()=>{const value=editor.value.trim();if(editor.dataset.listName){const item=state.lists.find(x=>x.id===editor.dataset.listName);if(item&&value)item.name=value;state.editingListId=null}else{const item=(state.groups||[]).find(x=>x.id===editor.dataset.groupName);if(item&&value)item.name=value;state.editingGroupId=null}render()};editor.addEventListener('click',e=>e.stopPropagation());editor.addEventListener('blur',finish,{once:true});editor.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();editor.blur()}if(e.key==='Escape'){e.preventDefault();editor.blur()}})}
}
function renderMain(){const m=document.querySelector('#main'),info=viewInfo(),tasks=filtered(),active=tasks.filter(t=>!t.completed),done=tasks.filter(t=>t.completed),dark=!['myday','daily'].includes(state.view);m.className='main'+(dark?' dark':'');const accents={important:'#f3a8bd',planned:'#81d8d0',tasks:'#7f9eff'};m.style.setProperty('--page-accent',accents[state.view]||'#fff');const theme=themes.find(x=>x[0]===state.theme)?.[1];m.style.background=!dark&&theme?theme:'';
  const cards=active.map(card).join('')+(done.length?`<button class="section-title" data-action="toggle-completed"><span class="section-chevron">⌄</span><span>Completed</span><span>${done.length}</span></button>${state.completedOpen?done.map(card).join(''):''}`:'');
  m.innerHTML=`<div class="main-content"><div class="page-head"><div><h1 class="heading"><span class="heading-icon">${info.icon}</span>${esc(info.name)}</h1>${state.view==='myday'?`<p class="page-subtitle">${new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric'}).format(new Date())}</p>`:''}</div><div class="head-actions"><button class="icon-btn menu-toggle" style="display:none" data-action="open-menu">☰</button>${state.view==='myday'?'<button class="icon-btn" data-action="suggestions" title="Suggestions">💡</button>':''}<button class="icon-btn" data-action="sort-menu" title="Sort">↕</button><button class="icon-btn" data-action="more" title="More">•••</button></div>${state.moreOpen?moreMenu():''}</div><div class="task-list">${cards||emptyState(info)}</div>${!['assigned','flagged'].includes(state.view)?`<form class="add-task" id="addTask"><span>＋</span><input name="title" autocomplete="off" placeholder="Add a task" aria-label="Add a task"></form>`:''}</div>`;
  m.querySelector('#addTask')?.addEventListener('submit',e=>{e.preventDefault();addTask(new FormData(e.target).get('title'));e.target.reset()})
}
function moreMenu(){return `<div class="more-menu"><button class="menu-row" data-action="sort-menu"><span>⇅</span><span>Sort by</span><b>›</b></button><div class="theme-label">Theme</div><div class="theme-grid">${themes.map(([id,color])=>`<button class="theme-swatch ${state.theme===id?'chosen':''}" data-theme="${id}" style="background:${color}" aria-label="Theme ${id}"></button>`).join('')}</div><div class="menu-sep"></div><button class="menu-row" data-action="print"><span>▣</span><span>Print list</span></button><button class="menu-row" data-action="jarvis"><span>✦</span><span>Send to Jarvis</span></button><button class="menu-row" data-action="pin"><span>⌖</span><span>Unpin from Start</span></button></div>`}
function emptyState(info){return `<div class="empty"><div><div class="empty-icon">${info.icon}</div><h2>${state.search?'No matching tasks':'All clear here'}</h2><p>${state.search?'Try another search':'Add a task to get started'}</p></div></div>`}
function card(t){let meta=[];if(state.view!=='tasks')meta.push(listName(t.list));if(t.myDay&&state.view!=='myday')meta.push('☼ My Day');if(t.due)meta.push(`<span class="${t.due<todayISO()?'overdue':''}">▦ ${t.due===todayISO()?'Today':formatDate(t.due)}</span>`);if(t.repeat)meta.push('↻ '+t.repeat);if(t.steps.length)meta.push(`${t.steps.filter(s=>s.done).length}/${t.steps.length}`);return `<article class="task-card ${state.selected===t.id?'selected':''}" data-task="${t.id}"><button class="check ${t.completed?'done':''}" data-action="complete" data-id="${t.id}" aria-label="${t.completed?'Mark as not completed':'Mark as completed'}">✓</button><div><div class="task-title ${t.completed?'done':''}">${esc(t.title)}</div><div class="meta">${meta.length?meta.join('<span>·</span>'):esc(listName(t.list))}</div></div><button class="star ${t.important?'important':''}" data-action="star" data-id="${t.id}" aria-label="Important">${t.important?'★':'☆'}</button></article>`}
function listName(id){return id==='tasks'?'Tasks':state.lists.find(l=>l.id===id)?.name||'Tasks'}
function formatDate(iso){return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric'}).format(new Date(iso+'T12:00:00'))}
function addTask(title){title=String(title||'').trim();if(!title)return;const list=builtIns.some(x=>x[0]===state.view)?'tasks':state.view;state.tasks.unshift({id:crypto.randomUUID(),title,list,important:state.view==='important',myDay:state.view==='myday',completed:false,due:state.view==='planned'?todayISO():null,reminder:null,repeat:null,note:'',steps:[],created:Date.now()});render();toast('Task added')}
function renderDetail(){const p=document.querySelector('#detailPanel'),t=state.tasks.find(x=>x.id===state.selected);if(!t){p.className='detail-panel';p.innerHTML='';return}p.className='detail-panel open';p.innerHTML=`<div class="panel-header"><span>Task details</span><button class="close-btn" data-action="close-detail">×</button></div><div class="detail-body"><div class="detail-card"><div class="detail-task"><div class="detail-title-row"><button class="check ${t.completed?'done':''}" data-action="complete" data-id="${t.id}">✓</button><input class="detail-title" data-field="title" value="${esc(t.title)}"><button class="star ${t.important?'important':''}" data-action="star" data-id="${t.id}">${t.important?'★':'☆'}</button></div></div><div class="step-list">${t.steps.map((s,i)=>`<div class="step"><input type="checkbox" data-step-done="${i}" ${s.done?'checked':''}><input type="text" data-step="${i}" value="${esc(s.title)}"><button class="delete-btn" data-remove-step="${i}">×</button></div>`).join('')}</div><div class="add-step">＋<input id="newStep" placeholder="Add step"></div></div><div class="detail-card"><button class="detail-action ${t.myDay?'active':''}" data-action="toggle-myday">☼　${t.myDay?'Added to My Day':'Add to My Day'}</button></div><div class="detail-card"><button class="detail-action" data-action="reminder">⏰　${t.reminder?formatDateTime(t.reminder):'Remind me'}</button><button class="detail-action" data-action="due">▦　${t.due?'Due '+formatDate(t.due):'Add due date'}</button><button class="detail-action" data-action="repeat">↻　${t.repeat||'Repeat'}</button></div><div class="detail-card"><button class="detail-action" data-action="file">♧　Add file</button></div><div class="detail-card"><textarea class="note" data-field="note" placeholder="Add note">${esc(t.note)}</textarea></div><div class="detail-footer"><span>Created ${formatDate(new Date(t.created).toISOString().slice(0,10))}</span><button class="delete-btn" data-action="delete" title="Delete">⌫</button></div></div>`;
  p.querySelectorAll('[data-field]').forEach(el=>el.addEventListener('change',()=>{t[el.dataset.field]=el.value;render()}));p.querySelector('#newStep').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.value.trim()){t.steps.push({title:e.target.value.trim(),done:false});render()}});p.querySelectorAll('[data-step]').forEach(el=>el.addEventListener('change',()=>{t.steps[+el.dataset.step].title=el.value;save()}));p.querySelectorAll('[data-step-done]').forEach(el=>el.addEventListener('change',()=>{t.steps[+el.dataset.stepDone].done=el.checked;save()}));p.querySelectorAll('[data-remove-step]').forEach(el=>el.addEventListener('click',()=>{t.steps.splice(+el.dataset.removeStep,1);render()}))
}
function formatDateTime(v){return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(v))}
function renderSuggestions(){const p=document.querySelector('#suggestionsPanel');if(!state.suggestions){p.className='suggestions-panel';p.innerHTML='';return}const candidates=state.tasks.filter(t=>!t.completed&&!t.myDay).slice(0,8);p.className='suggestions-panel open';p.innerHTML=`<div class="panel-header"><span>Suggestions</span><button class="close-btn" data-action="close-suggestions">×</button></div><div class="suggest-group"><div class="suggest-label"><span>Suggested</span><span>•••</span></div>${candidates.map(t=>`<div class="suggest-card"><button class="check" data-action="complete" data-id="${t.id}">✓</button><div><div>${esc(t.title)}</div><div class="meta">${esc(listName(t.list))}</div></div><button class="plus" data-action="suggest-add" data-id="${t.id}">＋</button></div>`).join('')||'<div class="empty"><p>Your day is already looking good</p></div>'}</div>`}
function modal(html){const d=document.createElement('div');d.className='modal-backdrop';d.innerHTML=`<div class="modal">${html}</div>`;document.body.append(d);d.addEventListener('click',e=>{if(e.target===d||e.target.matches('[data-modal-close]'))d.remove()});return d}
function nextUntitled(items,label){let n=1;const names=new Set(items.map(x=>x.name));while(names.has(n===1?label:`${label} (${n})`))n++;return n===1?label:`${label} (${n})`}
function newList(){const id='list-'+Date.now();state.lists.push({id,name:nextUntitled(state.lists,'Untitled list')});state.view=id;state.editingGroupId=null;state.editingListId=id;render()}
function newGroup(){state.groups=state.groups||[];const id='group-'+Date.now();state.groups.push({id,name:nextUntitled(state.groups,'Untitled group'),collapsed:false});state.editingListId=null;state.editingGroupId=id;render()}
function dateModal(kind){const t=state.tasks.find(x=>x.id===state.selected);if(!t)return;const value=(kind==='due'?t.due:(t.reminder||'').slice(0,10))||todayISO();const d=modal(`<h2>${kind==='due'?'Choose a due date':'Choose a reminder time'}</h2><input type="${kind==='due'?'date':'datetime-local'}" id="dateValue" value="${kind==='due'?value:value+'T09:00'}"><div class="modal-actions"><button class="btn" data-modal-close>Cancel</button><button class="btn primary" id="saveDate">Save</button></div>`);d.querySelector('#saveDate').onclick=()=>{const v=d.querySelector('#dateValue').value;if(kind==='due')t.due=v;else t.reminder=v;d.remove();render()}}
function repeatModal(){const t=state.tasks.find(x=>x.id===state.selected),d=modal(`<h2>Repeat</h2><select id="repeat"><option value="">Never</option><option>Daily</option><option>Weekly</option><option>Monthly</option><option>Yearly</option></select><div class="modal-actions"><button class="btn" data-modal-close>Cancel</button><button class="btn primary" id="saveRepeat">Save</button></div>`);d.querySelector('#repeat').value=t.repeat||'';d.querySelector('#saveRepeat').onclick=()=>{t.repeat=d.querySelector('#repeat').value;d.remove();render()}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;if(a.dataset.action==='new-group'){e.preventDefault();e.stopImmediatePropagation();newGroup()}else if(a.dataset.action==='toggle-group'){e.stopImmediatePropagation();const g=(state.groups||[]).find(x=>x.id===a.dataset.id);if(g){g.collapsed=!g.collapsed;render()}}});
document.addEventListener('click',e=>{const theme=e.target.closest('[data-theme]');if(theme){state.theme=theme.dataset.theme;state.moreOpen=false;render();return}const v=e.target.closest('[data-view]');if(v){state.view=v.dataset.view;state.selected=null;state.search='';state.sidebarOpen=false;state.moreOpen=false;render();return}const task=e.target.closest('[data-task]');const a=e.target.closest('[data-action]');if(task&&!a){state.selected=task.dataset.task;state.suggestions=false;render();return}if(!a){if(state.moreOpen&&!e.target.closest('.more-menu')){state.moreOpen=false;render()}return}const id=a.dataset.id,t=state.tasks.find(x=>x.id===id),selected=state.tasks.find(x=>x.id===state.selected);switch(a.dataset.action){case'complete':t.completed=!t.completed;render();toast(t.completed?'Task completed':'Task restored');break;case'star':t.important=!t.important;render();break;case'new-list':newList();break;case'close-detail':state.selected=null;render();break;case'suggestions':state.suggestions=!state.suggestions;state.selected=null;render();break;case'close-suggestions':state.suggestions=false;render();break;case'suggest-add':t.myDay=true;render();toast('Added to My Day');break;case'toggle-completed':state.completedOpen=!state.completedOpen;render();break;case'toggle-myday':selected.myDay=!selected.myDay;render();break;case'due':dateModal('due');break;case'reminder':dateModal('reminder');break;case'repeat':repeatModal();break;case'delete':state.tasks=state.tasks.filter(x=>x.id!==selected.id);state.selected=null;render();toast('Task deleted');break;case'file':toast('File uploads are unavailable; add a link in the note instead');break;case'more':state.moreOpen=!state.moreOpen;render();break;case'sort-menu':state.sortMode=state.sortMode==='created'?'important':state.sortMode==='important'?'alpha':'created';state.moreOpen=false;render();toast('Sorted by '+({created:'creation date',important:'importance',alpha:'name'}[state.sortMode]));break;case'print':window.jarvisDesktop?.openPrintPreview?window.jarvisDesktop.openPrintPreview():window.print();break;case'jarvis':state.moreOpen=false;render();toast(`Sent “${viewInfo().name}” to Jarvis`);break;case'pin':state.moreOpen=false;render();toast('Unpinned from Start');break;case'open-menu':state.sidebarOpen=true;render();break;case'home':state.view='myday';render();break}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='l'){e.preventDefault();newList();return}if(e.key==='Escape'){if(state.selected||state.suggestions||state.sidebarOpen){state.selected=null;state.suggestions=false;state.sidebarOpen=false;render()}}});
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),1800)}
render();
